mapper.update:
UPDATE transaction_flow
SET our_account = #{newAccountNo},
    our_company = #{newCompany},
    our_bank    = #{newBank},
    currency    = #{newCurrency}
WHERE our_account = #{oldAccountNo}

UPDATE transaction_flow
SET counterpart_account = #{newAccountNo},
    counterpart_bank    = #{newBank}
WHERE counterpart_account = #{oldAccountNo}

mapper.select:
SELECT COUNT(*)
FROM transaction_flow
WHERE our_account = #{accountNo}
   OR counterpart_account = #{accountNo}
